import {
    Flex,
} from '@mantine/core';
import type { Metadata } from 'next';
import { notFound, permanentRedirect } from 'next/navigation';
import { cache } from 'react';
import z from 'zod';

import { setGameResult } from '@/actions/setGameResult';
import { AutoRefresh } from '@/components/AutoRefresh/AutoRefresh';
import { GameDaySummary } from '@/components/GameDaySummary/GameDaySummary';
import { GameResultForm } from '@/components/GameResultForm/GameResultForm';
import { getUserRole } from '@/lib/auth.server';
import { formatDate } from '@/lib/dates';
import { getGameWinnersFromTeams } from '@/lib/gameResult';
import gameDayService from '@/services/GameDay';
import outcomeService from '@/services/Outcome';
import { FootyChannel } from '@/types/FootyChannel';

interface PageProps {
    params: Promise<{ id: string }>;
}

/**
 * Unpacks and validates route parameters for the game detail page.
 *
 * Validates the `id` parameter as a positive integer, retrieves the
 * corresponding game day, and handles redirects to the canonical URL if needed.
 *
 * @param params - The route parameters object containing the `id` property
 * @returns A promise that resolves to an object containing the validated
 * `gameDay`
 * @throws Calls `notFound()` if the game day cannot be found or the ID is
 * invalid
 * @throws Calls `permanentRedirect()` if the current URL doesn't match the
 * canonical URL
 */
const unpackParams = cache(async (
    params: PageProps['params'],
) => {
    const { id } = await params;

    const gameDayId = z.coerce.number().int().min(1).safeParse(id);
    const gameDay = gameDayId.success ? await gameDayService.get(gameDayId.data) : undefined;
    if (!gameDay) notFound();

    const canonicalUrl = `/footy/game/${gameDay.id}`;
    const currentUrl = `/footy/game/${id}`;
    if (currentUrl !== canonicalUrl) permanentRedirect(canonicalUrl);

    return { gameDay };
});

/**
 * Generates metadata for a game page.
 * @param props - The page props containing route parameters
 * @param props.params - Route parameters including the game ID
 * @returns A promise that resolves to metadata with the game title and date
 */
export async function generateMetadata(props: PageProps): Promise<Metadata> {
    const { gameDay } = await unpackParams(props.params);

    return {
        title: formatDate(gameDay.date),
    };
}

/**
 * Displays a football game day page with game details, team information, and
 * navigation.
 *
 * This is an async Server Component that fetches game data, determines user
 * role, and renders game results, player teams, and administrative controls
 * based on permissions.
 *
 * @component
 * @param {PageProps} props - The page component props
 * @param {object} props.params - Route parameters containing the game ID
 * @returns {Promise<React.ReactElement>} A flex container with game navigation,
 * admin controls, and game summary
 *
 * @remarks
 * - Fetches previous and next game days for navigation
 * - Retrieves team rosters (up to 10 players per team) for the current game day
 * - Calculates game winners from team data
 * - Only displays the GameResultForm if the user has an 'admin' role
 * - Navigation links (Previous/Next) are conditionally rendered based on data
 *   availability
 *
 * @requires getUserRole - To determine user permissions
 * @requires unpackParams - To extract gameDay from route params
 * @requires gameDayService.getPrevious - To fetch previous game
 * @requires gameDayService.getNext - To fetch next game
 * @requires outcomeService.getTeamPlayersByGameDay - To fetch team rosters
 * @requires getGameWinnersFromTeams - To calculate match winners
 */
const GamePage = async (props: PageProps) => {
    const { gameDay } = await unpackParams(props.params);
    const [role, prevGameDay, nextGameDay, teamA, teamB] = await Promise.all([
        getUserRole(),
        gameDayService.getPrevious(gameDay.id),
        gameDayService.getNext(gameDay.id),
        outcomeService.getTeamPlayersByGameDay(gameDay.id, 'A', 10),
        outcomeService.getTeamPlayersByGameDay(gameDay.id, 'B', 10),
    ]);
    const winners = getGameWinnersFromTeams(teamA, teamB);

    return (
        <Flex w="100%" direction="column" gap="md">
            <AutoRefresh channels={[FootyChannel.Games, FootyChannel.Results]} />
            <GameDaySummary
                gameDay={gameDay}
                prevGameDay={prevGameDay}
                nextGameDay={nextGameDay}
                teamA={teamA}
                teamB={teamB}
            />
            {role === 'admin' && !!gameDay.game && (
                <GameResultForm
                    gameDayId={gameDay.id}
                    bibs={gameDay.bibs ?? null}
                    winners={winners}
                    setGameResult={setGameResult}
                />
            )}
        </Flex>
    );
};

export default GamePage;

import {
    Flex,
    Group,
    Title,
} from '@mantine/core';
import { Metadata } from 'next';
import { notFound, permanentRedirect } from 'next/navigation';
import { cache } from 'react';
import z from 'zod';

import { AutoRefresh } from '@/components/AutoRefresh/AutoRefresh';
import { GameDayList } from '@/components/GameDayList/GameDayList';
import { TitleWithYearDropdown } from '@/components/TitleWithYearDropdown/TitleWithYearDropdown';
import { getYearName } from '@/lib/tables';
import gameDayService from '@/services/GameDay';
import { FootyChannel } from '@/types/FootyChannel';

interface PageProps {
    searchParams?: Promise<{
        year?: string;
    }>;
}

/**
 * Asynchronously unpacks and validates search parameters for the footy games
 * page, fetching relevant data such as available years, the current game day,
 * and game statistics.
 *
 * - Validates the `year` parameter from the search params, ensuring it is a
 *   valid year present in the list of all years.
 * - If the year is invalid or missing, triggers a 404 not found response.
 * - Fetches the number of games played, cancelled, and remaining for the
 *   specified year.
 * - Ensures the canonical URL structure by redirecting if the current URL does
 *   not match the canonical format.
 * - Constructs a title and subhead string summarizing the games data.
 *
 * @param searchParams - The search parameters from the page props, expected to
 * include a `year` query parameter.
 * @returns An object containing the validated year, all available years, the
 * current game day, a title, and a subhead string.
 * @throws Redirects to the canonical URL if the current URL is not canonical.
 * @throws Triggers a 404 not found response if the year is invalid or not
 * present in the available years.
 */
const unpackParams = cache(async (
    searchParams: PageProps['searchParams'],
) => {
    const [resolvedSearchParams, allYears, currentGameDay] = await Promise.all([
        searchParams,
        gameDayService.getAllYears({
            includeAllTime: true,
            mostRecentFirst: true,
        }),
        gameDayService.getCurrent(),
    ]);
    const yearResult = z.coerce.number().int().min(0).safeParse(resolvedSearchParams?.year ?? 0);
    const year = yearResult.success ? yearResult.data : undefined;
    if (year === undefined || !allYears.includes(year)) notFound();

    const [gamesPlayed, gamesCancelled, gamesRemaining] = await Promise.all([
        gameDayService.getGamesPlayed(year, currentGameDay?.id),
        gameDayService.getGamesCancelled(year, currentGameDay?.id),
        gameDayService.getGamesRemaining(year),
    ]);

    /* v8 ignore next -- year is always defined here; the notFound() guard above already excludes undefined */
    const canonicalSearch = year !== undefined ? `?year=${year}` : '';
    const canonicalUrl = `/footy/games/${canonicalSearch}`;
    const currentSearch = resolvedSearchParams?.year !== undefined ?
        `?year=${resolvedSearchParams.year}` :
        '';
    const currentUrl = `/footy/games/${currentSearch}`;
    if (currentUrl !== canonicalUrl) permanentRedirect(canonicalUrl);

    const title = `${year ? `${year} ` : ''}Games`;
    const subheadValues = [];
    if (gamesPlayed) subheadValues.push(`${gamesPlayed} played`);
    if (gamesCancelled) subheadValues.push(`${gamesCancelled} cancelled`);
    if (gamesRemaining) subheadValues.push(`${gamesRemaining} confirmed`);
    const subhead = subheadValues.join(', ');

    return { year, allYears, currentGameDay, title, subhead };
});

/**
 * Generates metadata for the footy games page based on the provided search
 * parameters. Fetches the year from the search parameters and constructs a
 * title for the page using the year name. If the year is not provided or
 * invalid, it defaults to a generic title.
 * @param props - The page properties containing search parameters.
 * @returns A promise that resolves to a Metadata object with the generated
 * title.
 * @throws Redirects to the canonical URL if the current URL is not canonical.
 * @throws Triggers a 404 not found response if the year is invalid or not
 * present in the available years.
 */
export async function generateMetadata(props: PageProps): Promise<Metadata> {
    const { year } = await unpackParams(props.searchParams);
    return { title: `${getYearName(year)} Games` };
}

/**
 * Server page component for displaying footy games. Fetches and validates the year from the search parameters, retrieves the list of game days for that year,
 * and renders a page with a title, subhead, and a list of game days. Also
 * includes an auto-refresh component that listens to relevant channels for
 * updates.
 * @param props - The page properties containing search parameters.
 * @returns A React element representing the games page.
 * @throws Redirects to the canonical URL if the current URL is not canonical.
 * @throws Triggers a 404 not found response if the year is invalid or not
 * present in the available years.
 * @remarks The page includes an auto-refresh mechanism that listens to the
 * "Games" and "Results" channels for real-time updates, ensuring that the
 * displayed data remains current without requiring manual refreshes.
 */
const GamesPage = async (props: PageProps) => {
    const { year, allYears, subhead } = await unpackParams(props.searchParams);
    const gameDays = await gameDayService.getAll({ year });

    return (
        <Flex w="100%" direction="column" align="center" gap="lg">
            <AutoRefresh channels={[FootyChannel.Games, FootyChannel.Results]} />
            <Group justify="center" w="100%">
                <TitleWithYearDropdown order={1} title="Games: " year={year} validYears={allYears} />
            </Group>
            <Title order={2} mb="xl">{subhead}</Title>
            <GameDayList gameDays={gameDays} year={year} />
        </Flex>
    );
};

export default GamesPage;

